"""기존 30문항: 현재 필터 구성의 과거형 재추출 및 필터 고정 대조 검색."""
import copy
import hashlib
import json
import sys
import time
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BC = ROOT / 'src/rag_home_api/test/bc'
RUN = BC / 'results/windows_20261125'
OUT = RUN / 'tense_comparison_filtered'
sys.path.insert(0, str(BC))


def read(path):
    return json.loads(path.read_text(encoding='utf-8'))


def write(path, value, mode='w'):
    with path.open(mode, encoding='utf-8') as stream:
        json.dump(value, stream, ensure_ascii=False, indent=2, allow_nan=False)


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def from_saved_plan(data):
    from query_filters import FilterPlan
    return FilterPlan(**{key: copy.deepcopy(data.get(key, [] if key != 'search_filter' else {}))
                         for key in ('search_filter', 'conditions', 'unsupported_conditions',
                                     'ambiguous_conditions', 'normalizations')})


def main():
    from run_filtered_dev import read_inputs, csv_hashes
    from run_course import accepted_transactions
    from lesson_pipeline import build_retrievers, format_context
    from query_filters import build_filter_extractor, resolve_building_plan, execute_query
    read_inputs()
    pairs_path = RUN / 'tense_comparison/question_pairs.json'
    pairs = read(pairs_path)
    questions = []
    for split in ('dev', 'test'):
        questions += [dict(q, split=split) for q in read(BC / f'eval/abc_{split}_questions.json')['questions']]
    questions_by_id = {q['id']: q for q in questions}
    current_rows = read(RUN / 'answer/results.json') + read(RUN / 'filtered_test_answer/results.json')
    current_metrics = read(RUN / 'answer/metrics.json')['details'] + read(RUN / 'filtered_test_answer/metrics.json')['details']
    current = {(r['question_id'], r['system']): r for r in current_rows}
    current_hit = {(r['question_id'], r['system']): r['hit_at_5'] for r in current_metrics}
    assert len(pairs) == len(questions) == 30 and len(current) == 90
    assert all(pair['current'] == questions_by_id[pair['id']]['question'] for pair in pairs)
    for config_file in (RUN / 'answer/config.json', RUN / 'filtered_test_answer/config.json'):
        config = read(config_file)
        for name in ('query_filters.py', 'lesson_pipeline.py', 'metadata_filters.py', 'structural_chunk_v0.py'):
            if config['code_sha256'][name] != sha(BC / name):
                raise ValueError(f'현재형 실행 이후 핵심 코드가 달라졌습니다: {name}')
    if OUT.exists():
        raise FileExistsError('과거형 필터 결과 폴더가 이미 있습니다.')
    OUT.mkdir(parents=True)
    write(OUT / 'config.json', {
        'experiment': 'filtered_past_tense_with_frozen_filter_control',
        'question_pairs_sha256': sha(pairs_path), 'csv_hashes': csv_hashes(),
        'variants': ['past_reextract', 'past_frozen_filter'],
        'current_baseline_files': ['answer/results.json', 'filtered_test_answer/results.json'],
        'current_baseline_sha256': {name: sha(RUN / name) for name in
                                    ('answer/results.json', 'filtered_test_answer/results.json')},
        'code_sha256': {name: sha(BC / name) for name in
                       ('query_filters.py', 'lesson_pipeline.py', 'metadata_filters.py')},
        'runner_sha256': sha(Path(__file__)), 'model': 'gpt-6-luna',
        'embedding_model': 'text-embedding-3-small', 'collection': 'course_v0_small',
        'reranker': 'Dongjin-kr/ko-reranker', 'max_length': 512,
        'k': 5, 'candidate_k': 20, 'rrf_c': 60, 'weights': [0.5, 0.5],
        'tokenizer': 'text.split()', 'answer_generation': False, 'final_v3_test_used': False,
        'scope': '현재형은 저장된 신규 필터 실행. 과거형은 같은 30문항을 최소 변환. '
                 '필터 고정 검색과 조건 재추출 검색을 분리. LLM 추출은 단회 실행이며 반복 안정성은 미측정.',
    }, 'x')
    write(OUT / 'results.json', [], 'x')
    accepted = accepted_transactions(questions)
    extractor = build_filter_extractor()
    records, plan_changes = [], []
    for pair in pairs:
        qid, query = pair['id'], pair['past']
        question = questions_by_id[qid]
        saved = current[(qid, 'A')]['plan']
        old_plan = from_saved_plan(saved)
        plan, extraction_error = None, None
        started = time.perf_counter()
        try:
            plan = resolve_building_plan(extractor.invoke(query))
        except Exception as error:
            extraction_error = type(error).__name__
        extraction_seconds = time.perf_counter() - started
        equivalent = bool(plan and plan.status == old_plan.status and plan.search_filter == old_plan.search_filter)
        plan_changes.append({'question_id': qid, 'split': pair['split'],
                             'filter_equal': bool(plan and plan.search_filter == old_plan.search_filter),
                             'routing_equal': bool(plan and plan.status == old_plan.status),
                             'equivalent_for_retrieval': equivalent,
                             'current_plan': saved, 'past_plan': plan.as_dict() if plan else None,
                             'extraction_error': extraction_error})
        primary_results = {}
        for variant, variant_plan in [('past_reextract', plan), ('past_frozen_filter', old_plan)]:
            retrievers, setup_error = None, None
            if not (variant == 'past_frozen_filter' and equivalent):
                if variant_plan is not None and variant_plan.status == 'ready':
                    try:
                        retrievers = build_retrievers('v0', 'small', search_filter=variant_plan.search_filter)
                    except Exception as error:
                        setup_error = type(error).__name__
            for system in ('A', 'B', 'C'):
                started = time.perf_counter()
                docs, contexts, response, status, error = [], [], None, None, None
                reused = variant == 'past_frozen_filter' and equivalent
                if reused:
                    record = copy.deepcopy(primary_results[system])
                    record.update({'variant': variant, 'reused_equivalent_result': True})
                else:
                    error = (extraction_error if variant == 'past_reextract' else None) or setup_error
                    try:
                        if error:
                            raise RuntimeError(error)
                        result = execute_query(query, variant_plan, 'retrieve', system, retrievers)
                        docs, response, status = result['documents'], result['response'], result['status']
                        contexts = [format_context(doc) for doc in docs]
                    except Exception as failure:
                        status, error = 'error', error or type(failure).__name__
                    hit = (int(status == 'success' and any(doc.metadata['id'] in accepted[qid] for doc in docs))
                           if question['reference_answerable'] else None)
                    record = {'question_id': qid, 'split': pair['split'], 'system': system, 'variant': variant,
                              'current_question': pair['current'], 'past_question': query,
                              'plan': variant_plan.as_dict() if variant_plan else None,
                              'status': status, 'error': error, 'response': response,
                              'hit_at_5': hit, 'current_hit_at_5': current_hit[(qid, system)],
                              'retrieved_ids': [doc.metadata['chunk_id'] for doc in docs],
                              'retrieved_contexts': contexts, 'returned_count': len(docs),
                              'seconds': time.perf_counter() - started,
                              'extraction_seconds': extraction_seconds, 'reused_equivalent_result': False}
                    if variant == 'past_reextract':
                        primary_results[system] = copy.deepcopy(record)
                records.append(record)
                write(OUT / 'results.json', records)
                print(qid, variant, system, record['status'], 'Hit@5', record['hit_at_5'], flush=True)
        write(OUT / 'plan_changes.json', plan_changes)
    summary = {'by_split': {}, 'plan_changes': plan_changes,
               'scope': '필터 재추출과 필터 고정 대조의 단회 탐색 비교. 답변 생성·RAGAS 미실행.'}
    for split in ('dev', 'test', 'all'):
        ids = {q['id'] for q in questions if q['reference_answerable'] and (split == 'all' or q['split'] == split)}
        summary['by_split'][split] = {}
        for variant in ('past_reextract', 'past_frozen_filter'):
            summary['by_split'][split][variant] = {}
            for system in ('A', 'B', 'C'):
                selected = {r['question_id']: r for r in records
                            if r['variant'] == variant and r['system'] == system and r['question_id'] in ids}
                summary['by_split'][split][variant][system] = {
                    'denominator': len(ids), 'current_hits': sum(current_hit[(qid, system)] or 0 for qid in ids),
                    'past_hits': sum(r['hit_at_5'] or 0 for r in selected.values()),
                    'gained': sorted(qid for qid in ids if not current_hit[(qid, system)] and selected[qid]['hit_at_5']),
                    'lost': sorted(qid for qid in ids if current_hit[(qid, system)] and not selected[qid]['hit_at_5']),
                    'errors': sum(r['status'] == 'error' for r in selected.values()),
                }
    summary['extraction_changed_questions'] = [p['question_id'] for p in plan_changes if not p['equivalent_for_retrieval']]
    write(OUT / 'summary.json', summary, 'x')
    print(json.dumps(summary['by_split'], ensure_ascii=False, indent=2), flush=True)
    print('Extraction changes:', summary['extraction_changed_questions'], flush=True)
    return int(any(r['status'] == 'error' for r in records))


if __name__ == '__main__':
    raise SystemExit(main())

